using System;using System.IO;using System.Reflection;using System.Windows.Forms;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class UiTests {
 static object Field(object obj,string name){return obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
 static void Call(object obj,string method,params object[] args){obj.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static IEnumerable<Control> Walk(Control c){foreach(Control k in c.Controls){yield return k;foreach(Control nested in Walk(k))yield return nested;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();int code=0;f.Shown+=(s,e)=>{try {
  var cues=(DataGridView)Field(f,"grid");Check(cues.Rows.Count==3,"Startup V15 sample displays without compatibility error");
  var bm=(ComboBox)Field(f,"breathMode");var settings=(FlowLayoutPanel)Field(f,"breathSettings");Check(bm.Items.Count==3&&bm.Items[0].ToString()=="Auto"&&bm.Items[1].ToString()=="Tùy chọn"&&bm.Items[2].ToString()=="Không dùng","Breath selector exposes exactly Auto, Custom, Off");
  bm.SelectedIndex=1;Application.DoEvents();Check(settings.Visible,"Custom mode displays WAV picker, level and frequency controls");bm.SelectedIndex=2;Application.DoEvents();Check(!settings.Visible,"Off mode hides custom breath controls");bm.SelectedIndex=0;
  var voices=(ComboBox)Field(f,"voices");Check(voices.Items.Cast<VoiceItem>().Count(v=>v.Name.StartsWith("★"))==3,"Three publisher-rated voices carry stars in selector");
  string temp=Path.Combine(Path.GetTempPath(),"v15_ui_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string a=Path.Combine(temp,"a.txt"),b=Path.Combine(temp,"b.txt");File.WriteAllText(a,"Have you ever forgotten why you entered a room?");File.WriteAllText(b,"Your brain may have switched contexts at the doorway.");Call(f,"AddFiles",new object[]{new string[]{a,b,a}});
  var jobs=(List<BatchJob>)Field(f,"jobs");var table=(DataGridView)Field(f,"jobGrid");Check(jobs.Count==2&&table.Rows.Count==2,"Multi-file import fills queue and deduplicates input path");
  Call(f,"LoadFile",a);Check((string)Field(f,"sourcePath")==a,"Single-file import remembers original directory for WAV output");Call(f,"LoadSample");Check(Field(f,"sourcePath")==null,"Pasted or sample scripts do not inherit a previous source file path");
  Call(f,"EditQueued");cues.Rows[0].Cells[3].Value="This changed sentence stays inside its own queued file.";Call(f,"ReadGrid");Check((string)Field(f,"sourcePath")==a,"Queued editor preserves its source path for beside-source export");Check(jobs[0].Cues[0].Text.StartsWith("This changed"),"Editing queued file updates only that queue entry");jobs[0].State=JobState.Done;Call(f,"ReadGrid");Check(jobs[0].State==JobState.Done,"Unchanged inspection preserves completed state for resume");
  var family=(ComboBox)Field(f,"family");var sf=(ComboBox)Field(f,"styleFilter");family.SelectedIndex=1;Check(voices.Items.Count==20,"LibriTTS selector is reduced to exactly 20 choices");sf.SelectedIndex=1;Check(voices.Items.Cast<VoiceItem>().All(v=>((VoiceCatalog)Field(f,"catalog")).Get(v.Key).MatchesStyle("Review")),"Studio style filter shows only matching profiles");sf.SelectedIndex=0;family.SelectedIndex=2;Check(voices.Items.Count==8,"Kitten family exposes eight mapped preset voices");family.SelectedIndex=3;Check(voices.Items.Count==2,"Piper family exposes John and Kristin");family.SelectedIndex=4;Check(voices.Items.Count==2,"Qwen exposes Aiden and Ryan presets");family.SelectedIndex=5;Check(voices.Items.Count==1,"Chatterbox exposes default voice and supports own references");family.SelectedIndex=0;
  var tabs=(TabControl)Field(f,"tabs");tabs.SelectedIndex=2;Application.DoEvents();var library=Walk(tabs.TabPages[2]).OfType<ListView>().First();Check(library.Items.Count==53,"Voice library displays only 53 curated and added voices");var filter=Walk(tabs.TabPages[2]).OfType<CheckBox>().First(c=>c.Text.StartsWith("★"));filter.Checked=true;Application.DoEvents();Check(library.Items.Count==9&&library.Items.Cast<ListViewItem>().All(r=>r.Text.StartsWith("★")),"Highly rated filter shows publisher picks and six V15 trial recommendations");
  var cat=(VoiceCatalog)Field(f,"catalog");var libraryStyle=Walk(tabs.TabPages[2]).OfType<ComboBox>().First();filter.Checked=false;libraryStyle.SelectedIndex=3;Application.DoEvents();Check(library.Items.Count>0&&library.Items.Cast<ListViewItem>().All(i=>cat.Get(Convert.ToString(i.Tag)).MatchesStyle("Bí ẩn / Dark curiosity")),"Library style filter matches the same per-voice tags");libraryStyle.SelectedIndex=0;Application.DoEvents();foreach(ListViewItem row in library.Items)row.Selected=false;library.Items.Cast<ListViewItem>().First(i=>Convert.ToString(i.Tag)=="P:john").Selected=true;sf.SelectedIndex=1;Walk(tabs.TabPages[2]).OfType<Button>().First(button=>button.Text=="Dùng giọng này").PerformClick();Check(family.SelectedIndex==3&&sf.SelectedIndex==0&&((VoiceItem)voices.SelectedItem).Key=="P:john","Use voice clears conflicting filters and selects the correct model");Check(((Label)Field(f,"voiceInfo")).Text.Contains("Phù hợp:"),"Selected voice always shows its recommended styles");family.SelectedIndex=0;tabs.SelectedIndex=2;
  var volume=(NumericUpDown)Field(f,"breathVolume");var frequency=(NumericUpDown)Field(f,"breathEvery");bm.SelectedIndex=1;volume.Value=22;frequency.Value=4;Call(f,"SaveBreathSettings");bm.SelectedIndex=2;volume.Value=12;Call(f,"LoadBreathSettings");Check(bm.SelectedIndex==1&&volume.Value==22&&frequency.Value==4,"Custom breath settings survive save and reload");bm.SelectedIndex=0;Call(f,"SaveBreathSettings");
  tabs.SelectedIndex=0;bm.SelectedIndex=1;var right=bm.Parent as ScrollableControl;Application.DoEvents();right.AutoScrollPosition=new System.Drawing.Point(0,2000);Application.DoEvents();using(var image=new System.Drawing.Bitmap(f.Width,f.Height)){using(var g=System.Drawing.Graphics.FromImage(image)){g.CopyFromScreen(f.Location,System.Drawing.Point.Empty,f.Size);}image.Save(Path.Combine(Path.GetTempPath(),"v15_140_breath.png"));}bm.SelectedIndex=0;right.AutoScrollPosition=System.Drawing.Point.Empty;
  // Capture actual screen while all tab layouts are visible in turn.
  foreach(int i in new[]{0,1,2}){tabs.SelectedIndex=i;Application.DoEvents();using(var image=new System.Drawing.Bitmap(f.Width,f.Height)){using(var g=System.Drawing.Graphics.FromImage(image)){g.CopyFromScreen(f.Location,System.Drawing.Point.Empty,f.Size);}image.Save(Path.Combine(Path.GetTempPath(),"v15_140_tab"+i+".png"));}}
 }catch(Exception x){Console.WriteLine("FAIL "+x);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
